# এসএসসি উচ্চতর গণিত অধ্যায় ১২ (সমতলীয় ভেক্টর): পাঠ্যবইয়ের ১৫ ও ১৬ নং সৃজনশীল (হুবহু) + সহজ ৪টি ও মধ্যম ৪টি (শুধু উত্তর/প্রমাণের মূল ধাপ)
# অভেদগুলো প্রতীকী ভেক্টর দিয়ে কোডে যাচাই করা
import json, os
from sympy import symbols, Matrix, Rational as R, simplify, solve
def P(n): return Matrix(symbols(n+'x '+n+'y'))
A,B,C,Dq,O=P('a'),P('b'),P('c'),P('d'),Matrix([0,0])
Z=lambda v: simplify(v)==Matrix([0,0])
mid=lambda p,q:(p+q)/2
# ১৫
D_,E_=mid(A,B),mid(A,C)
assert Z((D_-A)+(E_-D_)-(C-A)/2) and Z((E_-D_)-(C-B)/2)
M_,N_=mid(B,E_),mid(C,D_)   # BCED ট্রাপিজিয়ামের কর্ণ BE ও CD
assert Z((N_-M_)-((C-B)-(E_-D_))/2) and Z((N_-M_)-(C-B)/4)
# ১৬
Dm,Em,Fm=mid(B,C),mid(C,A),mid(A,B)
BE,CF,AB=Em-B,Fm-C,B-A
assert Z(AB+R(2,3)*(2*BE+CF)) and Z((Dm-A)+(Em-B)+(Fm-C)) and Z((Em-Fm)-(C-B)/2)
# সহজ
Dp=A+C-B   # সামান্তরিক ABCD
Oc=mid(A,C); assert Z(Oc-mid(B,Dp)) and Z((Dp-A)-((C-A)/2+(Dp-B)/2)) and Z((B-A)-((C-A)/2-(Dp-B)/2))
assert Z((B-A)-(C-Dp)) and Z((A+C)-(B+Dp))
assert Z((B-A)+(C-B)/2-(Dm-A)) and Z((B-A)+(C-A)-2*(Dm-A)) and Z((Em-Dm)-(A-B)/2)
Pp,Qp,Rp,Sp=mid(A,B),mid(B,C),mid(C,Dq),mid(Dq,A)
assert Z((Qp-Pp)-(C-A)/2) and Z((Rp-Sp)-(C-A)/2)
# মধ্যম
m=symbols('m'); AE=(D_-A)+m*(C-B)
coefB=simplify((AE).subs({}) ); # AE = (1/2 - m)AB + m AC ⇒ AC এর গুণিতক হতে হলে 1/2 − m = 0
assert solve(R(1,2)-m,m)==[R(1,2)] and Z(((D_-A)+R(1,2)*(C-B))-(C-A)/2)
k=symbols('k',positive=True); Dt=A+k*(C-B)   # ট্রাপিজিয়াম: AD ∥ BC নয়, AB ∥ DC → DC = t·AB
t=symbols('t',positive=True); Cq=Dq+t*(B-A)
Ee,Ff=mid(A,Dq),mid(B,Cq)
assert Z(2*(Ff-Ee)-((B-A)+(Cq-Dq))) and R(10+6,2)==8
Ob=O; Aq,Bq=A,B; Cc,Dd=2*Ob-Aq,2*Ob-Bq   # কর্ণ পরস্পরকে O তে সমদ্বিখণ্ডিত করে
assert Z((Bq-Aq)-(Cc-Dd)) and Z((Dd-Aq)-(Cc-Bq))
assert Z(Dm-(B+C)/2) and Z((Dm-O)+(Em-O)+(Fm-O)-(A+B+C)) and Z((Em-Dm)-(A-B)/2) and Z((Fm-Em)-(B-C)/2)
V=lambda s: s+'⃗'
CQ=[
('মধ্যম','ΔABC এর AB ও AC বাহুর মধ্যবিন্দু যথাক্রমে D ও E।',
 [f'({V("AD")} + {V("DE")}) কে {V("AC")} ভেক্টরের মাধ্যমে প্রকাশ কর।','ভেক্টরের সাহায্যে প্রমাণ কর যে, BC ∥ DE এবং DE = ½BC','BCED ট্রাপিজিয়ামের কর্ণদ্বয়ের মধ্যবিন্দু M ও N হলে ভেক্টরের সাহায্যে প্রমাণ কর যে, MN ∥ DE ∥ BC এবং MN = ½(BC − DE)'],
 f'ক) {V("AD")} + {V("DE")} = {V("AE")} = ½{V("AC")}\nখ) {V("DE")} = {V("AE")} − {V("AD")} = ½({V("AC")} − {V("AB")}) = ½{V("BC")} ⇒ DE ∥ BC এবং DE = ½BC\nগ) কর্ণ BE ও CD এর মধ্যবিন্দু M ও N ⇒ {V("MN")} = {V("MB")} + {V("BC")} + {V("CN")} = −½{V("BE")} + {V("BC")} + ½{V("CD")} = ½({V("BC")} − {V("DE")}) ; {V("BC")} ও {V("DE")} একই দিকে ⇒ MN ∥ DE ∥ BC এবং MN = ½(BC − DE)'),
('মধ্যম','ΔABC এর BC, CA ও AB বাহুর মধ্যবিন্দু যথাক্রমে D, E, F।',
 [f'{V("AB")} ভেক্টরকে {V("BE")} ও {V("CF")} ভেক্টরের মাধ্যমে প্রকাশ কর।',f'প্রমাণ কর যে, {V("AD")} + {V("BE")} + {V("CF")} = 0⃗','ভেক্টরের সাহায্যে প্রমাণ কর যে, F বিন্দু দিয়ে অঙ্কিত BC এর সমান্তরাল রেখা অবশ্যই E বিন্দুগামী হবে।'],
 f'ক) {V("AB")} = −⅔(2{V("BE")} + {V("CF")})\nখ) {V("AD")} = {V("AB")} + ½{V("BC")}, {V("BE")} = {V("BC")} + ½{V("CA")}, {V("CF")} = {V("CA")} + ½{V("AB")} ⇒ যোগফল = 3/2({V("AB")} + {V("BC")} + {V("CA")}) = 0⃗\nগ) {V("FE")} = {V("AE")} − {V("AF")} = ½({V("AC")} − {V("AB")}) = ½{V("BC")} ⇒ FE ∥ BC ; F দিয়ে BC এর সমান্তরাল রেখা একটিই, তাই তা E বিন্দুগামী'),
# ---- সহজ ৪
('সহজ','ABCD সামান্তরিকের কর্ণদ্বয় AC ও BD পরস্পর O বিন্দুতে ছেদ করেছে।',
 [f'{V("AB")} + {V("BC")} কে একটি কর্ণ ভেক্টরের মাধ্যমে প্রকাশ কর।','ভেক্টর পদ্ধতিতে প্রমাণ কর যে, সামান্তরিকের কর্ণদ্বয় পরস্পরকে সমদ্বিখণ্ডিত করে।',f'দেখাও যে, {V("AD")} = ½{V("AC")} + ½{V("BD")} এবং {V("AB")} = ½{V("AC")} − ½{V("BD")}'],
 f'ক) {V("AC")}\nখ) {V("AO")} = a⃗, {V("BO")} = b⃗, {V("OC")} = c⃗, {V("OD")} = d⃗ ধরে {V("AD")} = {V("BC")} ⇒ a⃗ + d⃗ = b⃗ + c⃗ ⇒ a⃗ − c⃗ = b⃗ − d⃗ ; বাম পক্ষের ধারক AC, ডান পক্ষের BD (ছেদী) ⇒ উভয়ই 0⃗ ⇒ |a⃗| = |c⃗|, |b⃗| = |d⃗|\nগ) {V("AD")} = {V("AO")} + {V("OD")} = ½{V("AC")} + ½{V("BD")} ; {V("AB")} = {V("AO")} + {V("OB")} = ½{V("AC")} − ½{V("BD")}'),
('সহজ','কোনো মূলবিন্দুর সাপেক্ষে A, B, C, D বিন্দুর অবস্থান ভেক্টর যথাক্রমে a⃗, b⃗, c⃗, d⃗',
 [f'{V("AB")} এবং {V("DC")} কে অবস্থান ভেক্টরের মাধ্যমে প্রকাশ কর।','প্রমাণ কর যে, ABCD সামান্তরিক হবে যদি এবং কেবল যদি b⃗ − a⃗ = c⃗ − d⃗ হয়।','ABCD সামান্তরিক হলে দেখাও যে, a⃗ + c⃗ = b⃗ + d⃗ এবং এ থেকে প্রমাণ কর যে, কর্ণদ্বয়ের মধ্যবিন্দু একই।'],
 f'ক) {V("AB")} = b⃗ − a⃗ ; {V("DC")} = c⃗ − d⃗\nখ) সামান্তরিক ⇔ {V("AB")} = {V("DC")} (সমান ও সমান্তরাল বিপরীত বাহু) ⇔ b⃗ − a⃗ = c⃗ − d⃗\nগ) পক্ষান্তর করে a⃗ + c⃗ = b⃗ + d⃗ ⇒ ½(a⃗ + c⃗) = ½(b⃗ + d⃗), অর্থাৎ AC ও BD এর মধ্যবিন্দুর অবস্থান ভেক্টর সমান'),
('সহজ','ΔABC এর BC বাহুর মধ্যবিন্দু D এবং CA বাহুর মধ্যবিন্দু E।',
 [f'{V("AD")} কে {V("AB")} ও {V("BC")} এর মাধ্যমে প্রকাশ কর।',f'প্রমাণ কর যে, {V("AB")} + {V("AC")} = 2{V("AD")}','ভেক্টরের সাহায্যে প্রমাণ কর যে, DE ∥ AB এবং DE = ½AB'],
 f'ক) {V("AD")} = {V("AB")} + ½{V("BC")}\nখ) {V("AD")} = {V("AB")} + {V("BD")} এবং {V("AD")} = {V("AC")} + {V("CD")} ; যোগ করে {V("BD")} + {V("CD")} = 0⃗ ⇒ 2{V("AD")} = {V("AB")} + {V("AC")}\nগ) {V("DE")} = {V("DC")} + {V("CE")} = ½{V("BC")} + ½{V("CA")} = ½{V("BA")} ⇒ DE ∥ AB, DE = ½AB'),
('সহজ','ABCD চতুর্ভুজের AB, BC, CD ও DA বাহুর মধ্যবিন্দু যথাক্রমে P, Q, R ও S।',
 [f'{V("PQ")} কে {V("AC")} এর মাধ্যমে প্রকাশ কর।',f'দেখাও যে, {V("SR")} = {V("PQ")}','ভেক্টর পদ্ধতিতে প্রমাণ কর যে, PQRS একটি সামান্তরিক।'],
 f'ক) {V("PQ")} = {V("PB")} + {V("BQ")} = ½{V("AB")} + ½{V("BC")} = ½{V("AC")}\nখ) {V("SR")} = {V("SD")} + {V("DR")} = ½{V("AD")} + ½{V("DC")} = ½{V("AC")} = {V("PQ")}\nগ) {V("PQ")} = {V("SR")} ⇒ PQ ও SR সমান ও সমান্তরাল ⇒ PQRS সামান্তরিক'),
# ---- মধ্যম ৪
('মধ্যম','ΔABC এর AB বাহুর মধ্যবিন্দু D। D বিন্দু দিয়ে অঙ্কিত BC এর সমান্তরাল রেখা AC কে E বিন্দুতে ছেদ করে।',
 [f'{V("AD")} কে {V("AB")} এর মাধ্যমে লিখ এবং {V("DE")} = m{V("BC")} কেন লেখা যায় তা ব্যাখ্যা কর।','ভেক্টরের সাহায্যে প্রমাণ কর যে, E বিন্দু AC এর মধ্যবিন্দু।','প্রমাণ কর যে, DE = ½BC'],
 f'ক) {V("AD")} = ½{V("AB")} ; DE ∥ BC বলে {V("DE")} একটি স্কেলার m এর জন্য m{V("BC")}\nখ) {V("AE")} = {V("AD")} + {V("DE")} = ½{V("AB")} + m({V("AC")} − {V("AB")}) = (½ − m){V("AB")} + m{V("AC")} ; {V("AE")}, {V("AC")} বরাবর ⇒ ½ − m = 0 ⇒ m = ½ ⇒ {V("AE")} = ½{V("AC")}\nগ) m = ½ ⇒ {V("DE")} = ½{V("BC")} ⇒ DE = ½BC'),
('মধ্যম','ABCD ট্রাপিজিয়ামে AB ∥ DC এবং অসমান্তরাল বাহু AD ও BC এর মধ্যবিন্দু যথাক্রমে E ও F।',
 [f'{V("EF")} কে দুইভাবে প্রকাশ কর: A ও B এর মধ্য দিয়ে এবং D ও C এর মধ্য দিয়ে।',f'প্রমাণ কর যে, 2{V("EF")} = {V("AB")} + {V("DC")}','প্রমাণ কর যে, EF ∥ AB ∥ DC এবং EF = ½(AB + DC)। AB = 10 সেমি ও DC = 6 সেমি হলে EF নির্ণয় কর।'],
 f'ক) {V("EF")} = {V("EA")} + {V("AB")} + {V("BF")} এবং {V("EF")} = {V("ED")} + {V("DC")} + {V("CF")}\nখ) যোগ করে {V("EA")} + {V("ED")} = 0⃗ ও {V("BF")} + {V("CF")} = 0⃗ ⇒ 2{V("EF")} = {V("AB")} + {V("DC")}\nগ) {V("AB")} ও {V("DC")} একই দিকে ⇒ {V("EF")} তাদের সমান্তরাল এবং EF = ½(AB + DC) ; EF = 8 সেমি'),
('মধ্যম','ABCD চতুর্ভুজের কর্ণদ্বয় AC ও BD পরস্পরকে O বিন্দুতে সমদ্বিখণ্ডিত করে।',
 [f'{V("AO")} ও {V("OC")} এবং {V("BO")} ও {V("OD")} এর সম্পর্ক লিখ।',f'প্রমাণ কর যে, {V("AB")} = {V("DC")}','প্রমাণ কর যে, ABCD একটি সামান্তরিক।'],
 f'ক) {V("AO")} = {V("OC")} এবং {V("BO")} = {V("OD")}\nখ) {V("AB")} = {V("AO")} + {V("OB")} = {V("OC")} + {V("DO")} = {V("DO")} + {V("OC")} = {V("DC")}\nগ) একইভাবে {V("AD")} = {V("AO")} + {V("OD")} = {V("OC")} + {V("BO")} = {V("BC")} ⇒ বিপরীত বাহুদ্বয় সমান ও সমান্তরাল ⇒ ABCD সামান্তরিক'),
('মধ্যম','O মূলবিন্দুর সাপেক্ষে A, B, C বিন্দুর অবস্থান ভেক্টর a⃗, b⃗, c⃗ এবং BC, CA, AB বাহুর মধ্যবিন্দু যথাক্রমে D, E, F।',
 ['D, E, F এর অবস্থান ভেক্টর নির্ণয় কর।',f'প্রমাণ কর যে, {V("OD")} + {V("OE")} + {V("OF")} = {V("OA")} + {V("OB")} + {V("OC")}','প্রমাণ কর যে, ΔDEF এর প্রতিটি বাহু ΔABC এর একটি বাহুর সমান্তরাল ও তার অর্ধেক।'],
 f'ক) D: ½(b⃗ + c⃗), E: ½(c⃗ + a⃗), F: ½(a⃗ + b⃗)\nখ) যোগফল = ½(2a⃗ + 2b⃗ + 2c⃗) = a⃗ + b⃗ + c⃗\nগ) {V("DE")} = ½(c⃗ + a⃗) − ½(b⃗ + c⃗) = ½(a⃗ − b⃗) = ½{V("BA")} ; একইভাবে {V("EF")} = ½{V("CB")}, {V("FD")} = ½{V("AC")}'),
]
items=[]
for i,(lv,st,p_,a_) in enumerate(CQ):
    assert len(p_)==3 and a_.count('ক)')==1 and a_.count('খ)')==1 and a_.count('গ)')==1, i
    items.append({'n':f'b{i+1}','ex':'সমন্বিত','stem':st,'p':p_,'a':a_,'lv':lv})
json.dump(items,open(os.path.join(os.path.dirname(os.path.abspath(__file__)),'cq_c10h_12.json'),'w'),ensure_ascii=False,indent=1); print('cq_c10h_12',len(items))
